mapper.select:
SELECT p.*,
       u1.real_name AS leaderName,
       u2.real_name AS teacherName,
       c.college_name AS collegeName,
       pc.cat_name AS catName
FROM project p
LEFT JOIN user u1 ON p.leader_id = u1.user_id
LEFT JOIN user u2 ON p.teacher_id = u2.user_id
LEFT JOIN college c ON p.college_id = c.college_id
LEFT JOIN project_category pc ON p.cat_id = pc.cat_id


        AND p.status = #{status}


        AND p.college_id = #{collegeId}


        AND p.apply_year = #{applyYear}


        AND p.project_name LIKE CONCAT('%', #{projectName}, '%')


        AND p.leader_id = #{leaderId}


        AND p.teacher_id = #{teacherId}


        AND (
            p.leader_id = #{memberUserId}
            OR EXISTS (SELECT 1 FROM project_member pm WHERE pm.project_id = p.project_id AND pm.user_id = #{memberUserId})
        )


ORDER BY p.apply_time DESC
